#include <iostream>
using namespace std;

int main() {
    int whole = 7;
    double decimal = whole;      // widening: automatic, nothing lost

    cout << "int:    " << whole << endl;
    cout << "double: " << decimal << endl;
    cout << "half:   " << decimal / 2 << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    double price = 7.9;

    int quiet = price;                       // allowed, but easy to miss
    int chopped = static_cast<int>(price);   // same result, on purpose

    cout << "double:  " << price << endl;
    cout << "quiet:   " << quiet << endl;
    cout << "chopped: " << chopped << endl;
    return 0;
}

