#include <iostream>
using namespace std;

int main() {
    int correct = 7;
    int total = 2;
    cout << correct / total << endl;
    cout << 7.0 / 2 << endl;
    double broken = correct / total;
    double fixed = static_cast<double>(correct) / total;
    cout << "broken: " << broken << endl;
    cout << "fixed:  " << fixed << endl;
    return 0;
}

