#include <iostream>
using namespace std;

int main() {
    char letter = 'A';
    int code = letter;                           // a char fits in an int

    int next = code + 1;
    char nextLetter = static_cast<char>(next);   // back to a character

    cout << letter << " has code " << code << endl;
    cout << "The next letter is " << nextLetter << endl;
    cout << 'A' + 'B' << endl;                   // adds the codes!
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string text = "42";
    int number = stoi(text);        // stoi: string to int
    double half = stod("0.5");      // stod: string to double

    cout << number + 8 << endl;
    cout << half * 3 << endl;
    return 0;
}

